import json,statistics
from pathlib import Path
root=Path(__file__).resolve().parents[1];folder=root/'runs/profiling/baseline';fixture=json.loads((folder/'fixture.json').read_text());lines=['# Baseline stage profile','', 'Ten calls in one process; first discarded. Source clip: %.3f s. TTS output duration differs from the source slot.'%fixture['source_seconds'],'','| Stage | Load + imports (s) | Warm inference (s) | RTF / source | RTF / stage audio | Peak Torch allocated (GiB) |','|---|---:|---:|---:|---:|---:|'];reports=[]
for name in ['asr','translation','tts','musetalk','ffmpeg']:
 r=json.loads((folder/f'{name}.json').read_text());reports.append(r);peak=r['peak_torch_allocated_bytes'];lines.append(f"| {name} | {r['load_seconds_including_imports']:.3f} | {r['mean_inference_seconds']:.3f} | {r['mean_inference_seconds']/fixture['source_seconds']:.3f} | {r['mean_rtf']:.3f} | {peak/2**30 if peak else 0:.3f} |")
muse=next(r for r in reports if r['stage']=='musetalk');lines+=['','## MuseTalk components','','| Component | Mean seconds | ms / video frame |','|---|---:|---:|']
for key in muse['runs'][1]['components_seconds']:
 seconds=statistics.mean(r['components_seconds'][key] for r in muse['runs'][1:]);lines.append(f'| {key} | {seconds:.3f} | {seconds/125*1000:.2f} |')
lines+=['','## Scope and limits','','- GPU stages synchronized before and after timing; load includes Python library imports and model initialization. First inference is reported separately in JSON.','- ASR and translation remain CPU baseline. Zero GPU allocated in the table means CPU execution; CPU RAM is not measured.','- Torch memory includes resident allocations and inference peak but excludes some driver/context allocations. Individual isolated peaks are not proof of concurrent fit.','- MuseTalk uses plain upstream v1.5 jaw blending, batch 2, fp16; no restorer or cached-avatar substitution. Face detection includes reading the already extracted PNG frames. A separate video decode is timed; PNG extraction writes are outside the repeated loop.','- FFmpeg row measures final encoding/muxing, not all preprocessing and per-segment encoding in the deployed service.','- TTS baseline uses its current float32 weights. Generated audio is approximately 6.15 seconds; comparing only output-audio RTF understates cost relative to the 5-second source slot.','- These isolated repeated-stage results are not an end-to-end pipeline or live latency benchmark. No claim that the realtime targets are met.']
(folder/'REPORT.md').write_text('\n'.join(lines)+'\n')
print('\n'.join(lines[:11]))
